import{_ as s,a0 as p,w as l,s as i,ao as d,I as o,x as t,a1 as a,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在FreeBSD 10.1中安裝Mate桌面 | LCTT x X-CMD","titleTemplate":false,"description":"在FreeBSD 10.1中安裝Mate桌面 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在FreeBSD 10.1中安裝Mate桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在FreeBSD 10.1中安裝Mate桌面 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150316 Install Mate desktop in FreeBSD 10.1","title":"在FreeBSD 10.1中安裝Mate桌面","tag":"201505","desc":""},"relativePath":"201505/20150316 Install Mate desktop in FreeBSD 10.1.md","filePath":"[post].md"}'),m={name:"201505/20150316 Install Mate desktop in FreeBSD 10.1.md"};function u(f,e,c,x,S,b){const n=p("Link");return l(),i("div",null,[e[13]||(e[13]=d(`<h1 id="在freebsd-10-1中安裝mate桌面" tabindex="-1">在FreeBSD 10.1中安裝Mate桌面 <a class="header-anchor" href="#在freebsd-10-1中安裝mate桌面" aria-label="Permalink to “在FreeBSD 10.1中安裝Mate桌面”">​</a></h1><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/03/FreeBSD-790x494.jpg" alt=""></p><p>FreeBSD是全文本模式的系統，然而有些新用户想要使用GUI桌面環境。這個教程就是幫助你在Freebsd 10.1中安裝Mate桌面。</p><p>下面是我的系統細節：</p><pre><code>root@Freebsd-unixmen:~ # uname -a
FreeBSD Freebsd-unixmen 10.1-RELEASE FreeBSD 10.1-RELEASE #0 r274401: Tue Nov 11 21:02:49 UTC 2014     root@releng1.nyi.freebsd.org:/usr/obj/usr/src/sys/GENERIC  amd64
root@Freebsd-unixmen:~
</code></pre><p>要在FreeBSD 10.1 中開始安裝Mate桌面，按照下面的步驟。</p><pre><code>pkg install xf86-video-fbdev mate-desktop mate xorg
</code></pre><h3 id="在-etc-rc-conf-中加入下面的行" tabindex="-1">在 /etc/rc.conf 中加入下面的行 <a class="header-anchor" href="#在-etc-rc-conf-中加入下面的行" aria-label="Permalink to “在 /etc/rc.conf 中加入下面的行”">​</a></h3><pre><code>moused_enable=&quot;YES&quot;
dbus_enable=&quot;YES&quot;
hald_enable=&quot;YES&quot;
</code></pre><h3 id="測試安裝" tabindex="-1">測試安裝 <a class="header-anchor" href="#測試安裝" aria-label="Permalink to “測試安裝”">​</a></h3><pre><code>xinit mate-session
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/03/snapshot2.png" alt=""></p><p>Mate本身沒有顯示管理器。因此我們會使用其他的顯示管理器如XDM、GDM、slim等等來作為登錄管理器。這裏讓我們看看如何在Mate桌面中配置Slim DM</p><h3 id="安裝-slim" tabindex="-1">安裝 Slim <a class="header-anchor" href="#安裝-slim" aria-label="Permalink to “安裝 Slim”">​</a></h3><pre><code>pkg install slim
</code></pre><p>在<strong>/etc/rc.conf</strong>中加入下面的行：</p><pre><code>slim_enable=&quot;YES&quot;
</code></pre><p>在用户的家目錄下的.xinitrc文件加入下面的行。</p><pre><code>exec mate-session
</code></pre><p>重啓電腦。現在在你登錄Mate時就會進入Slim登錄界面了。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/03/snapshot3.png" alt=""></p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/03/snapshot4.png" alt=""></p><p>就是這樣。乾杯！</p><hr>`,24)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),a(n,{href:"http://www.unixmen.com/install-mate-desktop-freebsd-10-1/"},{default:r(()=>[...e[0]||(e[0]=[t("http://www.unixmen.com/install-mate-desktop-freebsd-10-1/",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("作者：",-1)),a(n,{href:"http://www.unixmen.com/author/pirat9/"},{default:r(()=>[...e[2]||(e[2]=[t("M.el Khamlichi",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:r(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const D=s(m,[["render",u]]);export{w as __pageData,D as default};
